SELECT bip.*, bip.id AS process_id, dir.module_id, dir.form_id, dir.data_id, dir.data_name FROM bpm_inst_node_audit bina LEFT JOIN bpm_inst_process bip ON bip.id = bina.inst_process_id LEFT JOIN bpm_data_inst_rel dir ON dir.inst_process_id = bina.inst_process_id WHERE
OR ( bip.create_user_id = #{todoBo.userId}
